sp_widget.client_script:
api.controller = function($scope, $location, $window, $timeout) {
    var c = this;

    // UI Drawer & Modal State Controls
    c.sidebarCollapsed = false;
    c.showNotificationsPopover = false;
    c.showCreateProgramModal = false;
    c.showTrainerDrawer = false;
    c.showAddTrainerModal = false;
    c.showProgramDrawer = false;
    c.showStudentPerformanceModal = false;
    c.showAtRiskDrawer = false;
    c.showAnalyticsModal = false;
    c.showFullTableModal = false;

    // Active Tab in Program Detail Drawer
    c.programActiveTab = 'overview'; // 'overview', 'students', 'attendance', 'assessments', 'mock', 'progress'

    // Selected Objects
    c.selectedProgramDetail = null;
    c.selectedTrainerDetail = null;
    c.selectedStudentDetail = null;

    // Global Filters
    c.searchQuery = '';
    c.selectedProgram = '';
    c.selectedTrainer = '';
    c.selectedSkill = '';
    c.selectedBatch = '';
    c.selectedStatus = '';
    c.selectedEnrollStatus = '';
    c.selectedPerformance = '';

    // Forms
    c.programForm = {
        training_name: '',
        training_id: '',
        description: '',
        skill_area: 'Java',
        trainer_sys_id: '',
        batch: '2023-2027',
        start_date: new Date().toISOString().split('T')[0],
        end_date: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
        capacity: 50,
        status: 'Active',
        program_type: 'Bootcamp',
        target_audience: 'CSE, IT & Circuit Branches'
    };

    c.trainerForm = {
        trainer_name: '',
        trainer_id: '',
        email: '',
        phone: '',
        expertise: 'Java, Spring Boot, SQL',
        experience: 5,
        status: 'Active'
    };

    // Toggle Sidebar
    c.toggleSidebar = function() {
        c.sidebarCollapsed = !c.sidebarCollapsed;
    };

    // Toggle Notifications
    c.toggleNotifications = function(e) {
        if (e) e.stopPropagation();
        c.showNotificationsPopover = !c.showNotificationsPopover;
    };



    // -------------------------------------------------------------
    // DYNAMIC FILTERING & DYNAMIC KPI COMPUTATION
    // -------------------------------------------------------------
    c.getFilteredPrograms = function() {
        var programs = c.data.programs || [];
        var query = (c.searchQuery || '').toLowerCase().trim();

        return programs.filter(function(prg) {
            // Live Search
            if (query) {
                var matchName = (prg.name || '').toLowerCase().indexOf(query) !== -1;
                var matchId = (prg.program_id || '').toLowerCase().indexOf(query) !== -1;
                var matchTrainer = (prg.trainer_name || '').toLowerCase().indexOf(query) !== -1;
                var matchSkill = (prg.skill_area || '').toLowerCase().indexOf(query) !== -1;
                if (!matchName && !matchId && !matchTrainer && !matchSkill) return false;
            }

            if (c.selectedProgram && prg.name !== c.selectedProgram) return false;
            if (c.selectedTrainer && prg.trainer_name !== c.selectedTrainer) return false;
            if (c.selectedSkill && prg.skill_area !== c.selectedSkill) return false;
            if (c.selectedBatch && prg.batch !== c.selectedBatch) return false;
            if (c.selectedStatus && prg.status !== c.selectedStatus) return false;

            return true;
        });
    };

    // Dynamic KPIs based on filtered programs
    c.getKPIs = function() {
        var filtered = c.getFilteredPrograms();
        var totalPrg = filtered.length;
        var activePrg = 0;
        var enrolledSum = 0;
        var compSum = 0;
        var impSum = 0;

        filtered.forEach(function(p) {
            if (p.status === 'Active') activePrg++;
            enrolledSum += (p.enrolled || 0);
            compSum += (p.completion || 0);
            impSum += (p.improvementVal || 0);
        });

        var len = totalPrg || 1;
        return {
            totalPrograms: totalPrg,
            activePrograms: activePrg,
            activeTrainers: c.data.trainers ? c.data.trainers.length : 3,
            enrolledStudents: enrolledSum,
            completionRate: Math.round(compSum / len) + '%',
            avgImprovement: '+' + Math.round(impSum / len) + '%'
        };
    };

    // -------------------------------------------------------------
    // CREATE TRAINING PROGRAM MODAL
    // -------------------------------------------------------------
    c.openCreateProgramModal = function() {
        c.programForm = {
            training_name: '',
            training_id: 'TRN-' + Math.floor(Math.random() * 899 + 100),
            description: '',
            skill_area: 'Java',
            trainer_sys_id: c.data.trainers.length ? c.data.trainers[0].sys_id : '',
            batch: '2023-2027',
            start_date: new Date().toISOString().split('T')[0],
            end_date: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
            capacity: 50,
            status: 'Active',
            program_type: 'Bootcamp',
            target_audience: 'CSE & Circuit Branches'
        };
        c.showCreateProgramModal = true;
    };

    c.closeCreateProgramModal = function() {
        c.showCreateProgramModal = false;
    };

    c.saveTrainingProgram = function() {
        if (!c.programForm.training_name) {
            alert('Please enter a Training Program Name.');
            return;
        }

        var payload = {
            action: 'create_training_program',
            training_name: c.programForm.training_name,
            training_id: c.programForm.training_id,
            skill_area: c.programForm.skill_area,
            trainer_sys_id: c.programForm.trainer_sys_id,
            batch: c.programForm.batch,
            start_date: c.programForm.start_date,
            end_date: c.programForm.end_date,
            capacity: c.programForm.capacity,
            status: c.programForm.status
        };

        c.server.get(payload).then(function(res) {
            alert('Training Program successfully created in ServiceNow backend!');
            c.showCreateProgramModal = false;
            c.refreshData();
        });
    };

    // -------------------------------------------------------------
    // TRAINER MANAGEMENT DRAWER & ADD TRAINER MODAL
    // -------------------------------------------------------------
    c.openTrainerDrawer = function() {
        c.showTrainerDrawer = true;
    };

    c.closeTrainerDrawer = function() {
        c.showTrainerDrawer = false;
    };

    c.openAddTrainerModal = function() {
        c.trainerForm = {
            trainer_name: '',
            trainer_id: 'TR' + Math.floor(Math.random() * 899 + 100),
            email: '',
            phone: '',
            expertise: 'Java, Python, SQL',
            experience: 6,
            status: 'Active'
        };
        c.showAddTrainerModal = true;
    };

    c.closeAddTrainerModal = function() {
        c.showAddTrainerModal = false;
    };

    c.saveTrainer = function() {
        if (!c.trainerForm.trainer_name) {
            alert('Please enter Trainer Name.');
            return;
        }

        var payload = {
            action: 'create_trainer',
            trainer_name: c.trainerForm.trainer_name,
            trainer_id: c.trainerForm.trainer_id,
            email: c.trainerForm.email,
            phone: c.trainerForm.phone,
            expertise: c.trainerForm.expertise,
            experience: c.trainerForm.experience,
            status: c.trainerForm.status
        };

        c.server.get(payload).then(function() {
            alert('Trainer successfully registered in Trainer Master table!');
            c.showAddTrainerModal = false;
            c.refreshData();
        });
    };

    c.openTrainerDetail = function(trainer) {
        c.selectedTrainerDetail = trainer;
    };

    // -------------------------------------------------------------
    // TRAINING PROGRAM DETAIL DRAWER & MODAL COHORT OPENING
    // -------------------------------------------------------------
    c.openProgramDrawer = function(program) {
        c.selectedProgramDetail = program;
        c.programActiveTab = 'overview';
        c.showProgramDrawer = true;

        if (program) {
            var stus = program.students || c.data.students || [];
            var totalStus = stus.length || 12;

            // Generate program assignments tied to real program fields & real enrolled students
            program.assignments = [
                {
                    title: (program.skill_area || 'Core') + ' Practical Assignment 1 - ' + (program.name || 'Module'),
                    description: 'Comprehensive hands-on exercise covering ' + (program.skill_area || 'core concepts') + ' techniques and real-world problem statements.',
                    posted_date: program.start_date || '2026-09-22',
                    due_date: program.end_date || '2026-10-15',
                    submissions_count: Math.min(totalStus, Math.max(1, totalStus - 1)),
                    total_students: totalStus,
                    avg_score: program.avgScore || 85,
                    max_marks: 100,
                    status: 'Graded',
                    submissions: stus.slice(0, Math.min(stus.length, 5)).map(function(s) {
                        return {
                            student: s.name,
                            usn: s.usn,
                            submitted_on: program.start_date || '2026-09-25',
                            marks: s.assessmentAvg || 88,
                            status: 'Graded'
                        };
                    })
                },
                {
                    title: (program.name || 'Program') + ' - Capstone Assessment Project',
                    description: 'End-to-end cohort project submission evaluating skill proficiency and implementation standards.',
                    posted_date: program.start_date || '2026-09-25',
                    due_date: program.end_date || '2026-10-20',
                    submissions_count: Math.min(totalStus, Math.max(1, totalStus - 2)),
                    total_students: totalStus,
                    avg_score: Math.max(60, (program.avgScore || 85) - 3),
                    max_marks: 100,
                    status: 'Active',
                    submissions: stus.slice(0, Math.min(stus.length, 4)).map(function(s) {
                        return {
                            student: s.name,
                            usn: s.usn,
                            submitted_on: program.start_date || '2026-09-28',
                            marks: Math.min(100, (s.assessmentAvg || 80) + 4),
                            status: 'Graded'
                        };
                    })
                }
            ];

            // Generate program mock interviews tied to real trainer & real students
            program.mocks = [
                {
                    title: (program.name || 'Technical') + ' - Mock Interview Round 1',
                    evaluator: program.trainer_name || 'Dr. Anil Varma',
                    date: program.start_date || '2026-09-28',
                    time: '10:00 AM - 04:00 PM',
                    cleared_count: Math.min(totalStus, Math.max(1, totalStus - 2)),
                    total_candidates: totalStus,
                    clearance_rate: Math.round((Math.max(1, totalStus - 2) / totalStus) * 100) + '%',
                    feedback: 'Evaluated student domain knowledge in ' + (program.skill_area || 'training skills') + '. Strong problem solving demonstrated.',
                    candidates: stus.slice(0, Math.min(stus.length, 5)).map(function(s) {
                        return {
                            student: s.name,
                            usn: s.usn,
                            rating: (s.mockScore ? (s.mockScore / 20).toFixed(1) : '4.2'),
                            result: (s.risk === 'High Risk' ? 'Needs Retake' : 'Cleared'),
                            feedback: (s.risk === 'High Risk' ? 'Recommended further practice in core concepts.' : 'Strong technical presentation and clear answers.')
                        };
                    })
                }
            ];
        }
    };

    // When opening cohort from inside the full table floating modal:
    c.openProgramDrawerFromModal = function(program) {
        c.showFullTableModal = false; // Close the floating modal so side drawer is clean & unblocked
        c.openProgramDrawer(program);
    };

    c.closeProgramDrawer = function() {
        c.showProgramDrawer = false;
        c.selectedProgramDetail = null;
    };

    c.setProgramTab = function(tabName) {
        c.programActiveTab = tabName;
    };

    // Attendance Date Selection & Filter State
    c.selectedAttendanceDate = '2026-09-25';
    c.selectedAttendanceFilter = 'all';
    c.attendanceDatesList = ['2026-09-25', '2026-09-22', '2026-09-20', '2026-09-15', '2026-09-10'];

    // Assignment Modals
    c.showAssignmentDetailModal = false;
    c.selectedAssignmentDetail = null;

    c.openAssignmentDetail = function(assign) {
        c.selectedAssignmentDetail = assign;
        c.showAssignmentDetailModal = true;
    };

    c.closeAssignmentDetail = function() {
        c.showAssignmentDetailModal = false;
        c.selectedAssignmentDetail = null;
    };

    // Mock Interview Modals
    c.showMockDetailModal = false;
    c.selectedMockDetail = null;

    c.openMockDetail = function(mock) {
        c.selectedMockDetail = mock;
        c.showMockDetailModal = true;
    };

    c.closeMockDetail = function() {
        c.showMockDetailModal = false;
        c.selectedMockDetail = null;
    };

    // -------------------------------------------------------------
    // STUDENT PERFORMANCE POPUP MODAL
    // -------------------------------------------------------------
    c.openStudentPerformanceModal = function(student) {
        c.selectedStudentDetail = student;
        c.showStudentPerformanceModal = true;
    };

    c.closeStudentPerformanceModal = function() {
        c.showStudentPerformanceModal = false;
        c.selectedStudentDetail = null;
    };

    // -------------------------------------------------------------
    // AT-RISK STUDENTS DRAWER
    // -------------------------------------------------------------
    c.openAtRiskDrawer = function() {
        c.showAtRiskDrawer = true;
    };

    c.closeAtRiskDrawer = function() {
        c.showAtRiskDrawer = false;
    };

    // -------------------------------------------------------------
    // ANALYTICS & EXPORTS
    // -------------------------------------------------------------
    // -------------------------------------------------------------
    // FULL TABLE MODAL
    // -------------------------------------------------------------
    c.openFullTableModal = function() {
        c.showFullTableModal = true;
    };

    c.closeFullTableModal = function() {
        c.showFullTableModal = false;
    };

    c.openAnalyticsModal = function() {
        c.showAnalyticsModal = true;
    };

    c.closeAnalyticsModal = function() {
        c.showAnalyticsModal = false;
    };

    c.exportReport = function(reportType) {
        var programs = c.getFilteredPrograms();
        if (!programs.length) {
            alert('No program data available to export.');
            return;
        }

        var csvContent = 'data:text/csv;charset=utf-8,';
        csvContent += 'Program ID,Training Program,Skill Area,Trainer,Batch,Start Date,End Date,Capacity,Enrolled,Completion (%),Average Score (%),Status\n';

        programs.forEach(function(row) {
            var line = [
                '"' + row.program_id + '"',
                '"' + row.name + '"',
                '"' + row.skill_area + '"',
                '"' + row.trainer_name + '"',
                '"' + row.batch + '"',
                '"' + row.start_date + '"',
                '"' + row.end_date + '"',
                row.capacity,
                row.enrolled,
                row.completion,
                row.avgScore,
                '"' + row.status + '"'
            ].join(',');
            csvContent += line + '\n';
        });

        var encodedUri = encodeURI(csvContent);
        var link = document.createElement('a');
        link.setAttribute('href', encodedUri);
        link.setAttribute('download', reportType.replace(/\s+/g, '_') + '.csv');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    c.refreshData = function() {
        c.server.refresh();
    };


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 TPO TRAINING PROGRAMS
   FULLSCREEN + CUSTOM NAVBAR + VISIBLE PAGE SCROLLBAR
   ========================================================= */


/* =========================================================
   GLOBAL RESET
   IMPORTANT:
   Do NOT globally style every <main>, .container or .row.
   Those selectors can interfere with the Training page content.
   ========================================================= */

html,
body {
    width: 100% !important;
    height: 100% !important;

    min-width: 100% !important;
    min-height: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    overflow: hidden !important;

    background: #f8fafc !important;

    -webkit-font-smoothing: antialiased !important;
    text-rendering: optimizeLegibility !important;
}


/* =========================================================
   HIDE NATIVE SERVICENOW / SYSTEM ADMINISTRATOR NAVBAR
   ========================================================= */

body:has(.campus360-tpo-layout) #sp-header,
body:has(.campus360-tpo-layout) header#sp-header,
body:has(.campus360-tpo-layout) .sp-header,
body:has(.campus360-tpo-layout) .sp-header-wrapper,
body:has(.campus360-tpo-layout) .sp-header-content,
body:has(.campus360-tpo-layout) .sp-navbar,
body:has(.campus360-tpo-layout) .sp-navbar-wrapper,
body:has(.campus360-tpo-layout) .sp-navbar-container,
body:has(.campus360-tpo-layout) #sp-nav-bar,
body:has(.campus360-tpo-layout) .sp-nav-bar,
body:has(.campus360-tpo-layout) .sp-nav,
body:has(.campus360-tpo-layout) .portal-header,
body:has(.campus360-tpo-layout) .portal-navbar,
body:has(.campus360-tpo-layout) .portal-nav,
body:has(.campus360-tpo-layout) .header-nav,
body:has(.campus360-tpo-layout) .navpage-header,
body:has(.campus360-tpo-layout) .navpage-header-content,
body:has(.campus360-tpo-layout) .navbar,
body:has(.campus360-tpo-layout) nav.navbar,
body:has(.campus360-tpo-layout) header.navbar,
body:has(.campus360-tpo-layout) .navbar-default,
body:has(.campus360-tpo-layout) .navbar-inverse,
body:has(.campus360-tpo-layout) #responsiveNav {
    display: none !important;

    visibility: hidden !important;

    width: 0 !important;
    height: 0 !important;

    min-width: 0 !important;
    min-height: 0 !important;

    max-width: 0 !important;
    max-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    overflow: hidden !important;

    opacity: 0 !important;

    pointer-events: none !important;
}


/* =========================================================
   REMOVE NATIVE SERVICE PORTAL OUTER SPACING
   ========================================================= */

body:has(.campus360-tpo-layout) #sp-page,
body:has(.campus360-tpo-layout) #sp-main,
body:has(.campus360-tpo-layout) .sp-page,
body:has(.campus360-tpo-layout) .sp-main,
body:has(.campus360-tpo-layout) .sp-page-container,
body:has(.campus360-tpo-layout) #page_content,
body:has(.campus360-tpo-layout) .page,
body:has(.campus360-tpo-layout) .page-wrapper,
body:has(.campus360-tpo-layout) .main-content {
    width: 100% !important;

    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    border: 0 !important;
}


/* =========================================================
   HIDE COMMON SERVICENOW FOOTER / HEADER LAYERS
   SO THEY CANNOT OVERLAP THE SIDEBAR
   ========================================================= */

body:has(.campus360-tpo-layout) .sp-footer,
body:has(.campus360-tpo-layout) .portal-footer,
body:has(.campus360-tpo-layout) footer.sp-footer {
    display: none !important;

    visibility: hidden !important;

    height: 0 !important;

    overflow: hidden !important;
}


/* =========================================================
   ROOT APP
   ========================================================= */

.campus360-tpo-layout {
    position: fixed !important;

    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;

    width: 100vw !important;
    height: 100vh !important;

    min-width: 0 !important;
    min-height: 0 !important;

    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    display: block !important;

    overflow: hidden !important;

    background: #f8fafc !important;

    color: #0f172a !important;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Arial,
        sans-serif !important;

    z-index: 2147483647 !important;

    isolation: isolate !important;

    box-sizing: border-box !important;
}


.campus360-tpo-layout *,
.campus360-tpo-layout *::before,
.campus360-tpo-layout *::after {
    box-sizing: border-box !important;
}


.campus360-tpo-layout button,
.campus360-tpo-layout input,
.campus360-tpo-layout select,
.campus360-tpo-layout textarea {
    font-family: inherit !important;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.tpo-sidebar {
    position: fixed !important;

    top: 0 !important;
    left: 0 !important;
    bottom: 0 !important;

    width: 250px !important;
    min-width: 250px !important;
    max-width: 250px !important;

    height: 100vh !important;
    min-height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    display: flex !important;
    flex-direction: column !important;

    background:
        linear-gradient(
            180deg,
            #10092a 0%,
            #130d31 54%,
            #0d0822 100%
        ) !important;

    color: #ffffff !important;

    border-right: 1px solid #28213f !important;

    box-shadow:
        4px 0 18px rgba(10, 7, 30, 0.14) !important;

    z-index: 2147483000 !important;

    overflow-x: hidden !important;
    overflow-y: auto !important;

    scrollbar-width: none !important;
    -ms-overflow-style: none !important;

    transition:
        width 0.25s ease,
        min-width 0.25s ease,
        max-width 0.25s ease,
        transform 0.25s ease,
        opacity 0.2s ease !important;
}


.tpo-sidebar::-webkit-scrollbar,
.tpo-sidebar *::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;

    display: none !important;
}


/* =========================================================
   BRAND
   ========================================================= */

.sidebar-brand {
    width: 100% !important;

    min-height: 92px !important;
    height: 92px !important;

    padding: 20px !important;

    display: flex !important;
    align-items: center !important;

    gap: 13px !important;

    border-bottom: 1px solid rgba(255,255,255,0.08) !important;

    flex-shrink: 0 !important;
}


.brand-logo {
    width: 52px !important;
    height: 52px !important;

    min-width: 52px !important;

    border-radius: 15px !important;

    background:
        linear-gradient(
            135deg,
            #7b3aec 0%,
            #8c47ef 100%
        ) !important;

    color: #ffffff !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    font-size: 26px !important;
    font-weight: 900 !important;

    box-shadow:
        0 9px 20px rgba(112,69,232,0.25) !important;
}


.brand-text {
    min-width: 0 !important;

    display: flex !important;
    flex-direction: column !important;
}


.brand-title {
    display: block !important;

    color: #ffffff !important;

    font-size: 19px !important;

    line-height: 1 !important;

    font-weight: 900 !important;

    letter-spacing: -0.4px !important;

    white-space: nowrap !important;
}


.brand-sub {
    display: block !important;

    margin-top: 7px !important;

    color: #c7b8ec !important;

    font-size: 10px !important;

    font-weight: 800 !important;

    letter-spacing: 0.8px !important;
}


/* =========================================================
   SIDEBAR USER
   ========================================================= */

.sidebar-user {
    margin: 15px 13px 12px !important;

    padding: 13px !important;

    min-height: 72px !important;

    border-radius: 15px !important;

    background:
        linear-gradient(
            145deg,
            #1b1538,
            #21194a
        ) !important;

    border: 1px solid #342b58 !important;

    display: flex !important;
    align-items: center !important;

    gap: 11px !important;

    flex-shrink: 0 !important;

    box-shadow:
        0 5px 14px rgba(0,0,0,0.16) !important;
}


.user-avatar {
    width: 46px !important;
    height: 46px !important;

    min-width: 46px !important;

    border-radius: 50% !important;

    background:
        linear-gradient(
            135deg,
            #8b5cf6,
            #6935df
        ) !important;

    color: #ffffff !important;

    display: flex !important;

    align-items: center !important;
    justify-content: center !important;

    font-size: 13px !important;

    font-weight: 900 !important;

    box-shadow:
        0 4px 12px rgba(123,63,240,0.28) !important;
}


.user-info {
    min-width: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    justify-content: center !important;
}


.user-name {
    color: #ffffff !important;

    font-size: 14px !important;

    font-weight: 900 !important;

    line-height: 1.15 !important;
}


.user-role {
    color: #c2b0f2 !important;

    font-size: 9px !important;

    font-weight: 700 !important;

    margin-top: 4px !important;

    white-space: nowrap !important;

    overflow: hidden !important;

    text-overflow: ellipsis !important;
}


/* =========================================================
   SIDEBAR NAVIGATION
   ========================================================= */

.sidebar-nav {
    flex: 1 1 auto !important;

    min-height: 0 !important;

    width: 100% !important;

    padding: 3px 13px 28px !important;

    overflow-x: hidden !important;
    overflow-y: auto !important;

    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}


.sidebar-nav::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;

    display: none !important;
}


.nav-section-title {
    padding: 15px 12px 7px !important;

    color: #8f89a6 !important;

    font-size: 9px !important;

    font-weight: 900 !important;

    letter-spacing: 1.5px !important;

    text-transform: uppercase !important;

    line-height: 1.2 !important;
}


.nav-item {
    width: 100% !important;

    min-height: 43px !important;

    margin-bottom: 3px !important;

    padding: 0 12px !important;

    border-radius: 10px !important;

    display: flex !important;

    align-items: center !important;

    gap: 11px !important;

    color: #ece9f7 !important;

    background: transparent !important;

    text-decoration: none !important;

    font-size: 12px !important;

    font-weight: 700 !important;

    cursor: pointer !important;

    position: relative !important;

    z-index: 10 !important;

    transition:
        background .16s ease,
        color .16s ease,
        transform .16s ease !important;
}


.nav-item:hover {
    background: #211a43 !important;

    color: #ffffff !important;

    text-decoration: none !important;

    transform: translateX(1px) !important;
}


.nav-item.active {
    background:
        linear-gradient(
            90deg,
            #7b3aec 0%,
            #8742ee 100%
        ) !important;

    color: #ffffff !important;

    font-weight: 900 !important;

    box-shadow:
        0 7px 16px rgba(123,58,236,0.24) !important;
}


.nav-icon {
    width: 22px !important;

    min-width: 22px !important;

    text-align: center !important;

    color: #bcb3cf !important;

    font-size: 15px !important;

    line-height: 1 !important;
}


.nav-item.active .nav-icon,
.nav-item:hover .nav-icon {
    color: #ffffff !important;
}


.nav-label {
    flex: 1 !important;

    min-width: 0 !important;

    white-space: nowrap !important;

    overflow: hidden !important;

    text-overflow: ellipsis !important;
}


.nav-badge {
    min-width: 23px !important;

    height: 23px !important;

    padding: 0 6px !important;

    border-radius: 50% !important;

    background: #30225d !important;

    color: #cdbdff !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    font-size: 9px !important;

    font-weight: 900 !important;

    flex-shrink: 0 !important;
}


.nav-badge.purple {
    background: #a855f7 !important;

    color: #ffffff !important;
}


/* =========================================================
   COLLAPSED SIDEBAR
   ========================================================= */

.campus360-tpo-layout.sidebar-collapsed .tpo-sidebar {
    width: 0 !important;

    min-width: 0 !important;

    max-width: 0 !important;

    transform: translateX(-100%) !important;

    opacity: 0 !important;

    pointer-events: none !important;

    overflow: hidden !important;

    border-right: 0 !important;
}


.campus360-tpo-layout.sidebar-collapsed .tpo-main-wrapper {
    width: 100vw !important;

    margin-left: 0 !important;

    margin-right: 0 !important;
}


.campus360-tpo-layout.sidebar-collapsed .sidebar-brand,
.campus360-tpo-layout.sidebar-collapsed .sidebar-user,
.campus360-tpo-layout.sidebar-collapsed .sidebar-nav {
    opacity: 0 !important;

    pointer-events: none !important;
}


/* =========================================================
   MAIN WRAPPER
   THIS IS THE PAGE SCROLL CONTAINER
   ========================================================= */

.tpo-main-wrapper {
    position: fixed !important;

    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;

    left: 250px !important;

    width: calc(100vw - 250px) !important;

    height: 100vh !important;

    min-width: 0 !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #f8fafc !important;

    display: flex !important;
    flex-direction: column !important;

    overflow-x: hidden !important;

    /* IMPORTANT - visible page scrollbar */
    overflow-y: scroll !important;

    scrollbar-width: auto !important;

    scrollbar-color:
        #aaa2bd
        #f1f3f7 !important;

    z-index: 100 !important;

    transition:
        left .25s ease,
        width .25s ease !important;
}


/* =========================================================
   MAIN PAGE SCROLLBAR - CHROME / EDGE
   ========================================================= */

.tpo-main-wrapper::-webkit-scrollbar {
    width: 10px !important;

    height: 10px !important;

    display: block !important;
}


.tpo-main-wrapper::-webkit-scrollbar-track {
    background: #f1f3f7 !important;

    border-left: 1px solid #e2e5eb !important;
}


.tpo-main-wrapper::-webkit-scrollbar-thumb {
    background: #aaa2bd !important;

    border-radius: 8px !important;

    border: 2px solid #f1f3f7 !important;
}


.tpo-main-wrapper::-webkit-scrollbar-thumb:hover {
    background: #8f82ad !important;
}


/* =========================================================
   TOP NAVBAR
   ========================================================= */

.tpo-topbar {
    position: sticky !important;

    top: 0 !important;

    z-index: 10000 !important;

    width: 100% !important;

    height: 72px !important;

    min-height: 72px !important;

    max-height: 72px !important;

    flex-shrink: 0 !important;

    padding: 0 22px !important;

    background: #ffffff !important;

    border-bottom: 1px solid #e3e6ec !important;

    box-shadow:
        0 1px 4px rgba(15,23,42,.035) !important;

    display: flex !important;

    align-items: center !important;

    justify-content: space-between !important;
}


/* =========================================================
   TOPBAR LEFT
   ========================================================= */

.topbar-left {
    min-width: 0 !important;

    display: flex !important;

    align-items: center !important;

    gap: 14px !important;

    height: 100% !important;
}


/* =========================================================
   HAMBURGER
   ========================================================= */

.sidebar-toggle {
    width: 43px !important;

    height: 43px !important;

    min-width: 43px !important;

    padding: 0 !important;

    margin: 0 !important;

    border: 1px solid #dce1e9 !important;

    border-radius: 11px !important;

    background: #ffffff !important;

    color: #4f5c70 !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    font-size: 19px !important;

    line-height: 1 !important;

    cursor: pointer !important;

    outline: none !important;

    box-shadow: none !important;

    transition:
        background .15s ease,
        border-color .15s ease,
        color .15s ease,
        transform .15s ease !important;
}


.sidebar-toggle:hover {
    background: #f7f3ff !important;

    border-color: #d5c6f5 !important;

    color: #6937d8 !important;
}


.sidebar-toggle:active {
    transform: scale(.95) !important;
}


/* =========================================================
   PAGE TITLE BOX
   ========================================================= */

.topbar-page-box {
    min-width: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    justify-content: center !important;

    padding: 5px 11px !important;

    border-radius: 5px !important;
}


.topbar-page-kicker {
    color: #743cdb !important;

    font-size: 8px !important;

    font-weight: 950 !important;

    letter-spacing: 1.6px !important;

    line-height: 1 !important;
}


.topbar-page-title {
    margin-top: 5px !important;

    color: #10182b !important;

    font-size: 17px !important;

    font-weight: 950 !important;

    line-height: 1.1 !important;

    letter-spacing: -.2px !important;

    white-space: nowrap !important;
}


/* =========================================================
   TOPBAR RIGHT
   ========================================================= */

.topbar-right {
    min-width: 0 !important;

    display: flex !important;

    align-items: center !important;

    justify-content: flex-end !important;

    gap: 9px !important;

    height: 100% !important;

    margin-left: auto !important;

    position: relative !important;
}


/* =========================================================
   LEAN SEARCH BAR
   ========================================================= */

.topbar-search {
    width: 315px !important;

    height: 42px !important;

    min-width: 260px !important;

    position: relative !important;

    display: flex !important;

    align-items: center !important;

    flex-shrink: 1 !important;

    border: 1px solid #dfe4ec !important;

    border-radius: 11px !important;

    background: #ffffff !important;

    transition:
        border-color .15s ease,
        box-shadow .15s ease,
        background .15s ease !important;
}


.topbar-search:focus-within {
    border-color: #a98ae9 !important;

    background: #ffffff !important;

    box-shadow:
        0 0 0 3px rgba(123,63,240,.08) !important;
}


.topbar-search-icon {
    position: absolute !important;

    left: 14px !important;

    top: 50% !important;

    transform: translateY(-50%) !important;

    color: #713de0 !important;

    font-size: 15px !important;

    line-height: 1 !important;

    pointer-events: none !important;
}


.topbar-search-input {
    width: 100% !important;

    height: 100% !important;

    min-height: 42px !important;

    padding:
        0 14px 0 39px !important;

    margin: 0 !important;

    border: 0 !important;

    outline: 0 !important;

    background: transparent !important;

    color: #273047 !important;

    font-size: 11px !important;

    font-weight: 600 !important;

    border-radius: 11px !important;
}


.topbar-search-input::placeholder {
    color: #8d96a7 !important;

    font-size: 11px !important;

    font-weight: 600 !important;
}


/* =========================================================
   REFRESH + NOTIFICATION BUTTONS
   ========================================================= */

.topbar-action-button {
    position: relative !important;

    width: 42px !important;

    height: 42px !important;

    min-width: 42px !important;

    padding: 0 !important;

    margin: 0 !important;

    border-radius: 50% !important;

    border: 1px solid #dfe3eb !important;

    background: #ffffff !important;

    color: #59667a !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    font-size: 17px !important;

    line-height: 1 !important;

    cursor: pointer !important;

    outline: none !important;

    transition:
        background .15s ease,
        border-color .15s ease,
        color .15s ease,
        transform .15s ease !important;
}


.topbar-action-button:hover {
    background: #f7f3ff !important;

    border-color: #d3c4f4 !important;

    color: #6735d7 !important;
}


.topbar-action-button:active {
    transform: scale(.95) !important;
}


/* =========================================================
   NOTIFICATION
   ========================================================= */

.notif-wrapper {
    position: relative !important;

    display: flex !important;

    align-items: center !important;
}


.notification-button {
    position: relative !important;
}


.notification-dot {
    position: absolute !important;

    top: 7px !important;

    right: 7px !important;

    width: 7px !important;

    height: 7px !important;

    border-radius: 50% !important;

    background: #ed4764 !important;

    border: 1.5px solid #ffffff !important;

    display: block !important;
}


/* =========================================================
   NOTIFICATION POPOVER
   ========================================================= */

.notif-popover {
    position: absolute !important;

    top: 51px !important;

    right: 0 !important;

    width: 365px !important;

    max-width: calc(100vw - 30px) !important;

    background: #ffffff !important;

    border: 1px solid #e0e4eb !important;

    border-radius: 15px !important;

    box-shadow:
        0 18px 45px rgba(15,23,42,.16) !important;

    overflow: hidden !important;

    z-index: 20000 !important;
}


.notif-header {
    min-height: 61px !important;

    padding: 12px 14px !important;

    background: #fafbfe !important;

    border-bottom: 1px solid #e7e9ee !important;

    display: flex !important;

    align-items: center !important;

    justify-content: space-between !important;

    gap: 10px !important;
}


.notif-header-title {
    display: flex !important;

    align-items: center !important;

    gap: 7px !important;

    color: #283149 !important;

    font-size: 11px !important;

    font-weight: 900 !important;
}


.notif-header-title i {
    color: #7b3aec !important;

    font-size: 14px !important;
}


.notif-count {
    padding: 4px 8px !important;

    border-radius: 12px !important;

    background: #fff0f2 !important;

    color: #d4455b !important;

    font-size: 8px !important;

    font-weight: 900 !important;

    white-space: nowrap !important;
}


.notif-body {
    padding: 12px !important;

    max-height: 390px !important;

    overflow-y: auto !important;
}


.notif-card {
    display: flex !important;

    align-items: flex-start !important;

    gap: 9px !important;

    padding: 11px !important;

    border-radius: 10px !important;

    margin-bottom: 9px !important;

    border: 1px solid transparent !important;
}


.notif-card:last-child {
    margin-bottom: 0 !important;
}


.notif-card.high-risk {
    background: #fff5f6 !important;

    border-color: #f6dadd !important;
}


.notif-card.medium-risk {
    background: #fffbf0 !important;

    border-color: #f4e5bb !important;
}


.notif-card-icon {
    width: 31px !important;

    height: 31px !important;

    min-width: 31px !important;

    border-radius: 8px !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    font-size: 13px !important;
}


.danger-icon {
    background: #ffe5e8 !important;

    color: #d34b59 !important;
}


.warning-icon {
    background: #fff0c9 !important;

    color: #b97a12 !important;
}


.notif-info {
    min-width: 0 !important;

    flex: 1 !important;
}


.notif-info h6 {
    margin: 0 !important;

    color: #263047 !important;

    font-size: 10px !important;

    font-weight: 900 !important;

    line-height: 1.3 !important;
}


.notif-info p {
    margin: 4px 0 0 !important;

    color: #7c8495 !important;

    font-size: 9px !important;

    font-weight: 600 !important;

    line-height: 1.45 !important;
}


.notif-view-btn {
    align-self: center !important;

    height: 28px !important;

    padding: 0 9px !important;

    border-radius: 7px !important;

    border: 0 !important;

    color: #ffffff !important;

    font-size: 8px !important;

    font-weight: 900 !important;

    cursor: pointer !important;

    flex-shrink: 0 !important;
}


.danger-btn {
    background: #d34b59 !important;
}


.warning-btn {
    background: #c18a1b !important;
}


.info-btn {
    background: #377fc8 !important;
}


/* =========================================================
   TOPBAR DIVIDER
   ========================================================= */

.topbar-divider {
    width: 1px !important;

    height: 34px !important;

    margin: 0 5px !important;

    background: #e2e6ec !important;

    flex-shrink: 0 !important;
}


/* =========================================================
   PROFILE
   ========================================================= */

.topbar-user-profile {
    min-width: 0 !important;

    display: flex !important;

    align-items: center !important;

    gap: 8px !important;

    height: 100% !important;

    flex-shrink: 0 !important;
}


.avatar-circle.small {
    width: 40px !important;

    height: 40px !important;

    min-width: 40px !important;

    border-radius: 50% !important;

    background:
        linear-gradient(
            135deg,
            #7b3ff0,
            #7135d9
        ) !important;

    color: #ffffff !important;

    display: flex !important;

    align-items: center !important;

    justify-content: center !important;

    font-size: 11px !important;

    font-weight: 950 !important;

    box-shadow:
        0 4px 10px rgba(123,63,240,.16) !important;
}


.user-meta {
    display: flex !important;

    flex-direction: column !important;

    justify-content: center !important;

    min-width: 0 !important;
}


.user-display {
    color: #182134 !important;

    font-size: 11px !important;

    font-weight: 950 !important;

    line-height: 1.1 !important;

    white-space: nowrap !important;
}


.user-sub {
    margin-top: 3px !important;

    color: #939bab !important;

    font-size: 8px !important;

    font-weight: 700 !important;

    line-height: 1 !important;
}


.topbar-user-chevron {
    color: #5c6678 !important;

    font-size: 13px !important;

    margin-left: 1px !important;
}


/* =========================================================
   MAIN CONTENT
   ========================================================= */

.tpo-content-container {
    width: 100% !important;

    max-width: none !important;

    min-width: 0 !important;

    margin: 0 !important;

    padding:
        27px 32px 50px !important;

    background: #f8fafc !important;
}


/* =========================================================
   HERO
   ========================================================= */

.dashboard-hero {
    width: 100% !important;

    background: #ffffff !important;

    border-radius: 19px !important;

    padding: 27px 30px !important;

    display: flex !important;

    align-items: center !important;

    justify-content: space-between !important;

    gap: 25px !important;

    border: 1px solid #e2e7ef !important;

    box-shadow:
        0 4px 20px rgba(15,23,42,.035) !important;

    margin-bottom: 24px !important;
}


.hero-left {
    min-width: 0 !important;
}


.hero-tag {
    display: inline-flex !important;

    align-items: center !important;

    gap: 7px !important;

    padding: 5px 11px !important;

    border-radius: 20px !important;

    color: #7138d8 !important;

    background: #f2ecff !important;

    font-size: 9px !important;

    font-weight: 900 !important;

    letter-spacing: .9px !important;

    margin-bottom: 10px !important;
}


.hero-title {
    margin: 0 0 6px !important;

    color: #11172a !important;

    font-size: 31px !important;

    line-height: 1.05 !important;

    font-weight: 950 !important;

    letter-spacing: -.55px !important;
}


.hero-desc {
    margin: 0 !important;

    max-width: 760px !important;

    color: #6f788c !important;

    font-size: 12px !important;

    line-height: 1.55 !important;

    font-weight: 600 !important;
}


.hero-actions {
    display: flex !important;

    align-items: center !important;

    justify-content: flex-end !important;

    gap: 9px !important;

    flex-wrap: wrap !important;

    flex-shrink: 0 !important;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.btn-purple-solid {
    background: #7c3aed !important;

    color: #ffffff !important;

    font-weight: 800 !important;

    font-size: 10px !important;

    border: 1px solid #7c3aed !important;

    border-radius: 9px !important;

    padding: 10px 15px !important;

    box-shadow:
        0 6px 14px rgba(124,58,237,.20) !important;

    transition:
        background .15s ease,
        border-color .15s ease,
        transform .15s ease !important;

    cursor: pointer !important;

    white-space: nowrap !important;
}


.btn-purple-solid:hover {
    background: #6d28d9 !important;

    border-color: #6d28d9 !important;

    transform: translateY(-1px) !important;
}


.btn-emerald-solid {
    background: #10b981 !important;

    color: #ffffff !important;

    font-weight: 800 !important;

    font-size: 10px !important;

    border: 1px solid #10b981 !important;

    border-radius: 9px !important;

    padding: 10px 15px !important;

    box-shadow:
