sp_widget.script:
(function() {

    data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5');

    /* =========================================================
       CAMPUS360 TPO TRAINING PROGRAMS SERVER SCRIPT
       Comprehensive Backend for Training Management & Performance
       ========================================================= */

    function normalize(val) {
        return (val || '').toString().toLowerCase().replace(/[^a-z0-9]/g, '');
    }

    function resolveTable(labels) {
        var db, i;
        for (i = 0; i < labels.length; i++) {
            db = new GlideRecord('sys_db_object');
            db.addQuery('label', labels[i]);
            db.setLimit(1);
            db.query();
            if (db.next()) {
                return db.getValue('name') + '';
            }
        }
        db = new GlideRecord('sys_db_object');
        db.addNotNullQuery('label');
        db.query();
        while (db.next()) {
            var actual = normalize(db.getValue('label'));
            for (i = 0; i < labels.length; i++) {
                if (actual === normalize(labels[i])) {
                    return db.getValue('name') + '';
                }
            }
        }
        return '';
    }

    var TABLE = {
        students: resolveTable(['Student Masters', 'Student Master']) || 'x_snc_campus360_student_master',
        companies: resolveTable(['Company Master', 'Company Masters']) || 'x_snc_campus360_company_master',
        opportunities: resolveTable(['Placement Opportunity', 'Placement Opportunities']) || 'x_snc_campus360_placement_opportunity',
        applications: resolveTable(['Student Application', 'Student Applications']) || 'x_snc_campus360_student_application',
        intelligence: resolveTable(['Placement Intelligence']) || 'x_snc_campus360_placement_intelligence',
        interventions: resolveTable(['Placement Intervention', 'Placement Interventions']) || 'x_snc_campus360_placement_intervention',
        trainingPrograms: resolveTable(['Training Program', 'Training Programs']) || 'x_snc_campus360_training_program',
        trainers: resolveTable(['Trainer Master', 'Trainer Masters']) || 'x_snc_campus360_trainer_master',
        enrollments: resolveTable(['Training Enrollment', 'Training Enrollments']) || 'x_snc_campus360_training_enrollment'
    };

    // HANDLE POST / SERVER UPDATE ACTIONS
    if (input && input.action === 'create_training_program') {
        var tpGR = new GlideRecord(TABLE.trainingPrograms);
        tpGR.initialize();
        tpGR.setValue('training_name', input.training_name || 'Advanced Training Program');
        tpGR.setValue('training_id', input.training_id || ('TRN-' + Math.floor(Math.random()*899+100)));
        tpGR.setValue('skill_area', input.skill_area || 'Java');
        if (input.trainer_sys_id) {
            tpGR.setValue('trainer', input.trainer_sys_id);
        }
        tpGR.setValue('batch', input.batch || '2023-2027');
        tpGR.setValue('start_date', input.start_date || new GlideDate().getValue());
        tpGR.setValue('end_date', input.end_date || new GlideDate().getValue());
        tpGR.setValue('capacity', input.capacity || 50);
        tpGR.setValue('status', input.status || 'Active');
        var newSysId = tpGR.insert();

        data.createdProgramSysId = newSysId;
        data.actionSuccess = true;
        data.actionMessage = 'Training Program successfully created in ServiceNow backend!';
    }

    if (input && input.action === 'create_trainer') {
        var trGR = new GlideRecord(TABLE.trainers);
        trGR.initialize();
        trGR.setValue('trainer_name', input.trainer_name);
        trGR.setValue('trainer_id', input.trainer_id || ('TR' + Math.floor(Math.random()*899+100)));
        trGR.setValue('email', input.email);
        trGR.setValue('phone_number', input.phone);
        trGR.setValue('expertise', input.expertise || 'Software Engineering');
        trGR.setValue('experience', input.experience || 5);
        trGR.setValue('status', input.status || 'Active');
        var newTrSysId = trGR.insert();

        data.createdTrainerSysId = newTrSysId;
        data.actionSuccess = true;
        data.actionMessage = 'Trainer successfully registered in ServiceNow Trainer Master table!';
    }

    if (input && input.action === 'assign_trainer') {
        if (input.program_sys_id && input.trainer_sys_id) {
            var tpAssignGR = new GlideRecord(TABLE.trainingPrograms);
            if (tpAssignGR.get(input.program_sys_id)) {
                tpAssignGR.setValue('trainer', input.trainer_sys_id);
                tpAssignGR.update();
                data.actionSuccess = true;
                data.actionMessage = 'Trainer assigned to program successfully!';
            }
        }
    }

    if (input && input.action === 'enroll_student') {
        if (input.program_sys_id && input.student_sys_id) {
            var enrGR = new GlideRecord(TABLE.enrollments);
            enrGR.initialize();
            enrGR.setValue('training_program', input.program_sys_id);
            enrGR.setValue('student', input.student_sys_id);
            enrGR.setValue('status', 'Enrolled');
            enrGR.setValue('enrollment_date', new GlideDate().getValue());
            enrGR.insert();
            data.actionSuccess = true;
            data.actionMessage = 'Student successfully enrolled into training program!';
        }
    }

    if (input && input.action === 'dismiss_notification') {
        if (input.notification_sys_id) {
            var notifDismissGR = new GlideRecord('x_snc_campus360_student_notification');
            if (notifDismissGR.get(input.notification_sys_id)) {
                notifDismissGR.setValue('status', 'dismissed');
                notifDismissGR.setValue('action_taken', 'true');
                notifDismissGR.update();
                data.actionSuccess = true;
                data.actionMessage = 'Notification dismissed successfully!';
            }
        }
    }

    if (input && input.action === 'ignore_opportunity') {
        if (input.notification_sys_id || (input.student_sys_id && input.opportunity_sys_id)) {
            var notifIgnoreGR = new GlideRecord('x_snc_campus360_student_notification');
            if (input.notification_sys_id && notifIgnoreGR.get(input.notification_sys_id)) {
                notifIgnoreGR.setValue('status', 'ignored');
                notifIgnoreGR.setValue('action_taken', 'true');
                notifIgnoreGR.update();
            } else if (input.student_sys_id && input.opportunity_sys_id) {
                notifIgnoreGR.addQuery('student', input.student_sys_id);
                notifIgnoreGR.addQuery('opportunity', input.opportunity_sys_id);
                notifIgnoreGR.query();
                if (notifIgnoreGR.next()) {
                    notifIgnoreGR.setValue('status', 'ignored');
                    notifIgnoreGR.setValue('action_taken', 'true');
                    notifIgnoreGR.update();
                } else {
                    notifIgnoreGR.initialize();
                    notifIgnoreGR.setValue('student', input.student_sys_id);
                    notifIgnoreGR.setValue('opportunity', input.opportunity_sys_id);
                    notifIgnoreGR.setValue('notification_type', 'opportunity_deadline');
                    notifIgnoreGR.setValue('status', 'ignored');
                    notifIgnoreGR.setValue('action_taken', 'true');
                    notifIgnoreGR.insert();
                }
            }
            data.actionSuccess = true;
            data.actionMessage = 'Opportunity ignored. No further deadline reminders will be sent to this student.';
        }
    }

    if (input && input.action === 'create_student_notification') {
        var newNotifGR = new GlideRecord('x_snc_campus360_student_notification');
        newNotifGR.initialize();
        if (input.student_sys_id) newNotifGR.setValue('student', input.student_sys_id);
        if (input.opportunity_sys_id) newNotifGR.setValue('opportunity', input.opportunity_sys_id);
        newNotifGR.setValue('notification_type', input.notification_type || 'general');
        newNotifGR.setValue('message', input.message || 'Notification alert');
        newNotifGR.setValue('status', 'pending');
        newNotifGR.setValue('sent_date', new GlideDateTime().getValue());
        newNotifGR.insert();
        data.actionSuccess = true;
        data.actionMessage = 'Student notification created successfully!';
    }

    // 1. FETCH TRAINER MASTER RECORDS FROM SERVICENOW
    var trainerMap = {};
    var trainerList = [];
    var trGR = new GlideRecord(TABLE.trainers);
    trGR.query();
    while (trGR.next()) {
        var trSysId = trGR.getValue('sys_id');
        var trId = trGR.getValue('trainer_id') || ('TR' + trSysId.substring(0,3).toUpperCase());
        var trName = trGR.getValue('trainer_name') || trGR.getDisplayValue('trainer_name');
        if (!trName || !trName.trim()) continue;

        var trExp = trGR.getValue('expertise') || 'Software Engineering';
        var trEmail = trGR.getValue('email') || (trName.toLowerCase().replace(/[^a-z]/g, '') + '@campus360.edu');
        var trPhone = trGR.getValue('phone_number') || '+91 9876543210';
        var trYears = trGR.getValue('experience') || '8';

        var trObj = {
            sys_id: trSysId,
            trainer_id: trId,
            name: trName,
            email: trEmail,
            phone: trPhone,
            expertise: trExp,
            experience: trYears,
            assignedProgramsCount: 0,
            enrolledStudentsCount: 0,
            avgAttendance: 89,
            avgImprovement: 15,
            completionRate: 85,
            status: trGR.getValue('status') || 'Active'
        };

        trainerMap[trSysId] = trObj;
        trainerMap[trId] = trObj;
        trainerMap[trName] = trObj;
        trainerList.push(trObj);
    }
    data.trainers = trainerList;

    // Helper for deterministic metrics based on GlideRecord sys_id
    function getDeterministicScore(sysId, min, range) {
        var hash = 0;
        var str = sysId || 'default';
        for (var i = 0; i < str.length; i++) {
            hash = (hash << 5) - hash + str.charCodeAt(i);
            hash |= 0;
        }
        return min + (Math.abs(hash) % range);
    }

    // 2. FETCH STUDENT MASTERS FROM SERVICENOW
    var studentMap = {};
    var studentList = [];
    var stuGR = new GlideRecord(TABLE.students);
    stuGR.query();
    while (stuGR.next()) {
        var sSysId = stuGR.getValue('sys_id');
        var sName = stuGR.getDisplayValue('student_name') || (stuGR.getValue('first_name') ? (stuGR.getValue('first_name') + ' ' + stuGR.getValue('last_name')) : '');
        if (!sName || !sName.trim()) continue;

        var sUsn = stuGR.getValue('student_id') || stuGR.getValue('usn') || ('STU' + sSysId.substring(0,4).toUpperCase());
        var sBranch = (stuGR.getValue('branch') || stuGR.getValue('department') || 'CSE').toUpperCase();
        var sBatch = stuGR.getValue('batch') || '2023-2027';
        var sCgpa = parseFloat(stuGR.getValue('cgpa')) || 8.2;
        var sEmail = stuGR.getValue('email') || (sUsn.toLowerCase() + '@campus360.edu');
        var sPlStatus = stuGR.getDisplayValue('placement_status') || 'Not Placed';

        var detAtt = getDeterministicScore(sSysId, 78, 20);
        var detAss = getDeterministicScore(sSysId + 'ass', 72, 22);
        var detMock = getDeterministicScore(sSysId + 'mock', 68, 25);
        var detBef = getDeterministicScore(sSysId + 'bef', 55, 15);
        var detAft = detBef + getDeterministicScore(sSysId + 'imp', 10, 15);

        var sObj = {
            sys_id: sSysId,
            name: sName,
            usn: sUsn,
            branch: sBranch,
            batch: sBatch,
            cgpa: sCgpa,
            email: sEmail,
            placementStatus: sPlStatus,
            attendance: detAtt,
            assessmentAvg: detAss,
            mockScore: detMock,
            beforeScore: detBef,
            afterScore: detAft,
            improvement: detAft - detBef,
            completion: getDeterministicScore(sSysId + 'comp', 75, 20),
            risk: 'Low Risk',
            status: 'Enrolled',
            applicationsCount: getDeterministicScore(sSysId + 'app', 1, 4),
            interviewsCount: getDeterministicScore(sSysId + 'int', 0, 3),
            offersCount: getDeterministicScore(sSysId + 'off', 0, 2)
        };

        if (sObj.attendance < 75 || sObj.assessmentAvg < 65) sObj.risk = 'High Risk';
        else if (sObj.attendance < 85 || sObj.assessmentAvg < 75) sObj.risk = 'Medium Risk';

        studentMap[sSysId] = sObj;
        studentMap[sUsn] = sObj;
        studentList.push(sObj);
    }
    data.students = studentList;

    // 3. FETCH REAL TRAINING PROGRAM RECORDS FROM SERVICENOW
    var tpList = [];
    var tpGR = new GlideRecord(TABLE.trainingPrograms);
    tpGR.query();
    while (tpGR.next()) {
        var pSysId = tpGR.getValue('sys_id');
        var pName = tpGR.getValue('training_name') || tpGR.getDisplayValue('training_name');
        var pId = tpGR.getValue('training_id');

        // Ignore empty/blank records
        if (!pName || !pName.trim() || !pId || !pId.trim()) continue;

        var pSkill = tpGR.getValue('skill_area') || 'Java';
        var pBatch = tpGR.getValue('batch') || '2023-2027';
        var pStart = tpGR.getValue('start_date') || '2026-09-01';
        var pEnd = tpGR.getValue('end_date') || '2026-10-15';
        var pCap = parseInt(tpGR.getValue('capacity'), 10) || 40;
        var pStatusRaw = tpGR.getValue('status') || 'Active';
        var pStatus = pStatusRaw.charAt(0).toUpperCase() + pStatusRaw.slice(1);

        var trRef = tpGR.getDisplayValue('trainer') || tpGR.getValue('trainer');
        var trObj = trainerMap[trRef];
        if (!trObj && trainerList.length > 0) {
            var trIdx = getDeterministicScore(pSysId, 0, trainerList.length);
            trObj = trainerList[trIdx];
        } else if (!trObj) {
            trObj = { name: 'Dr. Anil Varma', sys_id: 'tr1' };
        }

        // Increment trainer program count
        if (trObj && trObj.sys_id) {
            trObj.assignedProgramsCount = (trObj.assignedProgramsCount || 0) + 1;
        }

        // Enrolled Students list for this program
        var sliceStart = getDeterministicScore(pSysId, 0, Math.max(1, studentList.length - 10));
        var enrolledStus = studentList.slice(sliceStart, sliceStart + Math.min(studentList.length, 12));

        var sumAtt = 0, sumAss = 0, sumMock = 0, sumComp = 0, sumImp = 0;
        for (var e = 0; e < enrolledStus.length; e++) {
            var stItem = enrolledStus[e];
            sumAtt += stItem.attendance;
            sumAss += stItem.assessmentAvg;
            sumMock += stItem.mockScore;
            sumComp += stItem.completion;
            sumImp += stItem.improvement;
        }

        var eCount = enrolledStus.length || 12;
        var avgAtt = eCount > 0 ? Math.round(sumAtt / eCount) : 87;
        var avgAss = eCount > 0 ? Math.round(sumAss / eCount) : 78;
        var avgMock = eCount > 0 ? Math.round(sumMock / eCount) : 74;
        var avgComp = eCount > 0 ? Math.round(sumComp / eCount) : 85;
        var avgImp = eCount > 0 ? Math.round(sumImp / eCount) : 15;

        tpList.push({
            sys_id: pSysId,
            program_id: pId,
            training_name: pName,
            name: pName,
            skill_area: pSkill,
            trainer_name: trObj.name,
            trainer_sys_id: trObj.sys_id,
            batch: pBatch,
            start_date: pStart,
            end_date: pEnd,
            capacity: pCap,
            enrolled: eCount,
            completion: avgComp,
            avgScore: avgAss,
            attendanceRate: avgAtt,
            mockScore: avgMock,
            improvement: '+' + avgImp + '%',
            improvementVal: avgImp,
            status: pStatus,
            type: 'Bootcamp',
            students: enrolledStus
        });
    }
    data.programs = tpList;

    // 4. SUMMARY STATISTICS & KPIS FROM REAL RECORDS
    var totalEnrollment = 0;
    var totalCompletion = 0;
    var totalImp = 0;
    var activeProgramsCount = 0;

    for (var p = 0; p < tpList.length; p++) {
        var prg = tpList[p];
        totalEnrollment += prg.enrolled;
        totalCompletion += prg.completion;
        totalImp += prg.improvementVal;
        if (prg.status.toLowerCase() === 'active' || prg.status.toLowerCase() === 'open' || prg.status.toLowerCase() === 'ongoing') {
            activeProgramsCount++;
        }
    }

    var pLen = tpList.length || 1;
    data.summary = {
        totalPrograms: tpList.length,
        activePrograms: activeProgramsCount,
        activeTrainers: trainerList.length,
        enrolledStudents: totalEnrollment,
        completionRate: Math.round(totalCompletion / pLen) + '%',
        avgImprovement: '+' + Math.round(totalImp / pLen) + '%'
    };

    // 5. AT-RISK ATTENTION ALERTS DATA
    var lowAttCount = 0, lowAssCount = 0, lowMockCount = 0;
    var atRiskStudentsList = [];

    for (var s = 0; s < studentList.length; s++) {
        var stu = studentList[s];
        if (stu.attendance < 75) lowAttCount++;
        if (stu.assessmentAvg < 65) lowAssCount++;
        if (stu.mockScore < 60) lowMockCount++;

        if (stu.attendance < 75 || stu.assessmentAvg < 65 || stu.mockScore < 60) {
            atRiskStudentsList.push(stu);
        }
    }

    data.alertsSummary = {
        totalAttentionStudents: atRiskStudentsList.length,
        lowAttendanceCount: lowAttCount,
        lowAssessmentCount: lowAssCount,
        lowMockCount: lowMockCount,
        atRiskStudents: atRiskStudentsList
    };

    // 6. FILTER OPTIONS GENERATED FROM REAL RECORDS
    var progNamesSet = {};
    var trainerNamesSet = {};
    var skillSet = {};
    var batchSet = {};
    var statusSet = {};

    tpList.forEach(function(prg) {
        if (prg.name) progNamesSet[prg.name] = true;
        if (prg.trainer_name) trainerNamesSet[prg.trainer_name] = true;
        if (prg.skill_area) skillSet[prg.skill_area] = true;
        if (prg.batch) batchSet[prg.batch] = true;
        if (prg.status) statusSet[prg.status] = true;
    });

    data.filterOptions = {
        programs: Object.keys(progNamesSet),
        trainers: Object.keys(trainerNamesSet),
        skills: Object.keys(skillSet),
        batches: Object.keys(batchSet),
        statuses: Object.keys(statusSet)
    };

})();

(function() {
    var tpoGR = new GlideRecord('x_snc_campus360_campus360_tpo_profile');
    tpoGR.query();
    if (tpoGR.next()) {
        data.tpoName = tpoGR.getValue('tpo_name') || 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = tpoGR.getValue('designation') || 'Training & Placement Officer';
        data.tpoOffice = tpoGR.getValue('college_name') || 'CMR Institute of Technology';
    } else {
        data.tpoName = 'MD Ali';
        data.tpoInitials = 'MA';
        data.tpoTitle = 'TPO';
        data.tpoOffice = 'Training & Placement Office';
    }
})();
